"use server";

import { supabase } from "@/lib/supabase";

export async function submitWaitlist(formData: FormData) {
  const email = formData.get("email") as string;
  const note = formData.get("note") as string | null;

  if (!email) {
    return { error: "Email is required" };
  }

  try {
    const { data, error } = await supabase
      .from("waitlist")
      .insert([
        {
          email,
          note: note || null,
        },
      ])
      .select();

    if (error) {
      console.error("Supabase error:", error);
      // Return more helpful error message in development
      if (error.message.includes("relation") && error.message.includes("does not exist")) {
        return { error: "Database table not found. Please run the SQL setup script in Supabase." };
      }
      if (error.message.includes("permission denied") || error.message.includes("policy")) {
        return { error: "Permission denied. Please check RLS policies in Supabase." };
      }
      return { error: `Failed to submit: ${error.message}` };
    }

    return { success: true };
  } catch (error) {
    console.error("Unexpected error:", error);
    return { error: error instanceof Error ? error.message : "Something went wrong. Please try again." };
  }
}
