"use client";

import { useEffect, useState } from "react";
import AnimatedText from "./AnimatedText";

export default function Hero() {
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setMousePosition({
        x: (e.clientX / window.innerWidth) * 100,
        y: (e.clientY / window.innerHeight) * 100,
      });
    };

    window.addEventListener("mousemove", handleMouseMove);
    return () => window.removeEventListener("mousemove", handleMouseMove);
  }, []);

  return (
    <section className="min-h-screen flex items-center justify-center px-4 py-20 relative bg-gradient-spiritual overflow-hidden">
      {/* Dynamic floating orbs that follow mouse */}
      <div 
        className="absolute top-20 left-10 w-32 h-32 bg-lavender/30 rounded-full blur-2xl float transition-all duration-1000 ease-out"
        style={{
          transform: `translate(${(mousePosition.x - 50) * 0.1}px, ${(mousePosition.y - 50) * 0.1}px)`,
        }}
      ></div>
      <div 
        className="absolute bottom-20 right-10 w-40 h-40 bg-sky/30 rounded-full blur-2xl float-delayed transition-all duration-1000 ease-out"
        style={{
          transform: `translate(${(mousePosition.x - 50) * -0.1}px, ${(mousePosition.y - 50) * -0.1}px)`,
        }}
      ></div>
      <div 
        className="absolute top-1/2 right-20 w-24 h-24 bg-peach/30 rounded-full blur-xl bounce-gentle transition-all duration-1000 ease-out"
        style={{
          transform: `translate(${(mousePosition.x - 50) * 0.05}px, ${(mousePosition.y - 50) * 0.05}px)`,
        }}
      ></div>
      
      <div className="max-w-6xl mx-auto text-center space-y-10 relative z-10">
        <div className="space-y-4">
          <AnimatedText
            text="Music that gets you. Like, actually gets you."
            className="text-5xl md:text-7xl lg:text-8xl font-bold leading-[1.1] gradient-text-vibrant"
            delay={200}
            wordDelay={100}
          />
        </div>
        
        <p className="text-xl md:text-2xl text-charcoal/80 font-medium max-w-3xl mx-auto animate-fade-in-delay-1">
          No cap. Just 60 seconds of vibes that match your energy. 
          <span className="gradient-text-2 font-semibold"> Real talk, real feels.</span>
        </p>
        
        <div className="pt-12 animate-fade-in-delay-2">
          <a
            href="#waitlist"
            className="group inline-block relative"
          >
            <div className="absolute inset-0 bg-gradient-to-r from-lavender via-indigo to-sky rounded-full blur-xl opacity-60 group-hover:opacity-80 transition-opacity duration-500 animate-pulse-slow"></div>
            <div className="relative px-12 py-5 bg-gradient-to-r from-lavender via-indigo to-sky text-white text-lg font-semibold rounded-full transition-all duration-500 hover:scale-110 hover:shadow-2xl hover:shadow-indigo/50 active:scale-95 overflow-hidden">
              <span className="relative z-10 flex items-center gap-2">
                <span>Something cool is coming</span>
                <span className="text-2xl animate-bounce-gentle">✨</span>
              </span>
              <div className="absolute inset-0 shimmer"></div>
            </div>
          </a>
        </div>
        
        <div className="flex items-center justify-center gap-2 text-sm text-charcoal/50 animate-fade-in-delay-3">
          <span className="w-2 h-2 rounded-full bg-lavender animate-pulse"></span>
          <span>Join the waitlist</span>
          <span className="w-2 h-2 rounded-full bg-indigo animate-pulse" style={{ animationDelay: '0.2s' }}></span>
          <span>Early access</span>
          <span className="w-2 h-2 rounded-full bg-sky animate-pulse" style={{ animationDelay: '0.4s' }}></span>
          <span>Lifetime perks</span>
        </div>
      </div>
    </section>
  );
}
